'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 368,
  "height": 144,
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "Valid Appointments",
          "as": "lo"
        },
        {
          "op": "max",
          "field": "Valid Appointments",
          "as": "hi"
        }
      ]
    },
    {
      "calculate": "(datum[''Valid Appointments''] - datum.lo) / max(datum.hi - datum.lo, 1e-9)",
      "as": "t"
    },
    {
      "calculate": "format(datum[''Valid Appointments''] / 1000, ''.1f'') + ''k''",
      "as": "vtxt"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 6
      },
      "encoding": {
        "x": {
          "field": "Time of Day",
          "type": "ordinal",
          "sort": [
            "Early AM",
            "Late AM",
            "Afternoon",
            "Evening"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Early AM",
              "Late AM",
              "Afternoon",
              "Evening"
            ],
            "paddingInner": 0.06
          },
          "axis": {
            "orient": "top",
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10
          }
        },
        "y": {
          "field": "Weekday",
          "type": "ordinal",
          "sort": [
            "Mon",
            "Tue",
            "Wed",
            "Thu",
            "Fri",
            "Sat",
            "Sun"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Mon",
              "Tue",
              "Wed",
              "Thu",
              "Fri",
              "Sat",
              "Sun"
            ],
            "paddingInner": 0.1
          },
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "color": {
          "field": "Valid Appointments",
          "type": "quantitative",
          "legend": null,
          "scale": {
            "range": [
              "#EFECFC",
              "#4A3AA7"
            ]
          }
        },
        "tooltip": [
          {
            "field": "Weekday"
          },
          {
            "field": "Time of Day"
          },
          {
            "field": "Valid Appointments",
            "format": ","
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 11,
        "fontWeight": 600,
        "dy": 0
      },
      "encoding": {
        "x": {
          "field": "Time of Day",
          "type": "ordinal",
          "sort": [
            "Early AM",
            "Late AM",
            "Afternoon",
            "Evening"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Early AM",
              "Late AM",
              "Afternoon",
              "Evening"
            ],
            "paddingInner": 0.06
          },
          "axis": {
            "orient": "top",
            "labelAngle": 0,
            "labelColor": "#667085",
            "labelFontSize": 10
          }
        },
        "y": {
          "field": "Weekday",
          "type": "ordinal",
          "sort": [
            "Mon",
            "Tue",
            "Wed",
            "Thu",
            "Fri",
            "Sat",
            "Sun"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Mon",
              "Tue",
              "Wed",
              "Thu",
              "Fri",
              "Sat",
              "Sun"
            ],
            "paddingInner": 0.1
          },
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "text": {
          "field": "vtxt"
        },
        "color": {
          "condition": {
            "test": "datum.t >= 0.5",
            "value": "#FFFFFF"
          },
          "value": "#101828"
        }
      }
    }
  ],
  "autosize": {
    "type": "pad"
  }
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
